function slug(s){return (s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function keyStatus(s){return s==='Ativo'?'active':s==='Inativo'?'inactive':s==='Em ativação'?'activation':'reactivation'}function tag(s){return `<span class="tag ${keyStatus(s)}">${esc(s)}</span>`}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function isPublicChapter(c){return c.status==='Ativo'&&c.published===true}
function isMapHighlightedChapter(c){
 const raw=String(c.raw?.status??c.status??'').toLowerCase().replace(/[áàâã]/g,'a').replace(/[éê]/g,'e').replace(/[í]/g,'i').replace(/[óôõ]/g,'o').replace(/[ú]/g,'u').replace(/\s+/g,'_');
 const normalized=raw==='ativo'?'active':raw==='em_ativacao'?'in_activation':raw==='em_reativacao'?'reactivation':raw;
 return normalized==='active'||normalized==='in_activation'||normalized==='reactivation'||c.status==='Ativo'||c.status==='Em ativação'||c.status==='Em reativação';
}
function mapChapterStatusLabel(c){
 const raw=String(c.raw?.status??c.status??'').toLowerCase();
 if(['active','ativo'].includes(raw)||c.status==='Ativo')return 'Capítulo ativo';
 if(['in_activation','em_implantacao','em_implantacao','em ativação','em implantacao','em implantação'].includes(raw)||c.status==='Em ativação')return 'Capítulo em implantação/ativação';
 if(['reactivation','em_reativacao','em reativação'].includes(raw)||c.status==='Em reativação')return 'Capítulo em reativação';
 return c.status||raw||'Situação não informada';
}function adhLocalDateISO(date=new Date()){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}
