async function saveChapter(ev){
 ev.preventDefault();if(!canEdit('chapter'))return;if(!adhSession)return openRealLogin();
 const f=ev.target,d=new FormData(f),id=editingChapter;
 const municipalityId=String(d.get('city')||''),regionId=String(d.get('region')||'');
 if(!municipalityId||!regionId){toast('Selecione um município e uma região cadastrados no Supabase.');return}
 const body={name:String(d.get('name')||'').trim(),municipality_id:Number(municipalityId),region_id:Number(regionId),status:String(d.get('status')||'inactive'),address:String(d.get('address')||'').trim()||null,is_public:d.get('published')==='yes'};
 if(!body.name){toast('Informe o nome do capítulo.');return}
 const btn=f.querySelector('button[type="submit"]');if(btn)btn.disabled=true;
 try{
   const path='/rest/v1/chapters'+(id?('?id=eq.'+encodeURIComponent(id)):'');
   const saved=await adhFetch(path,{method:id?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(body)});
   await loadChaptersAdmin();closeModal('chapterModal');renderAll();log(id?'Capítulo atualizado no Supabase':'Capítulo criado no Supabase',body.name,'Registro persistido no banco.');toast('Capítulo salvo no Supabase.');
 }catch(e){toast('Falha ao salvar capítulo no Supabase: '+e.message);}
 finally{if(btn)btn.disabled=false}
}
async function togglePublic(id){
 if(!canEdit('chapter'))return;if(!adhSession)return openRealLogin();
 const c=chapters.find(x=>String(x.id)===String(id));if(!c)return;
 const next=!c.published;
 try{await adhFetch('/rest/v1/chapters?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({is_public:next})});await loadChaptersAdmin();renderAll();toast(next?'Publicação habilitada no Supabase.':'Capítulo despublicado no Supabase.');}
 catch(e){toast('Falha ao alterar publicação: '+e.message)}
}
async function loadChaptersAdmin(){
 if(!adhSession)throw new Error('É necessário autenticar-se como administrador estadual.');
 const [rows,munis,regs]=await Promise.all([
  adhFetch('/rest/v1/chapters?select=id,name,chapter_number,municipality_id,region_id,address,status,is_public,president_name,vice_president_name&order=name.asc&limit=2000'),
  adhFetch('/rest/v1/municipalities?select=id,name&order=name.asc&limit=1000'),
  adhFetch('/rest/v1/regions?select=id,name&order=name.asc&limit=500')
 ]);
 adhDbChapters=Array.isArray(rows)?rows:[];adhDbMunicipalities=Array.isArray(munis)?munis:[];adhDbRegions=Array.isArray(regs)?regs:[];
 const mm=new Map(adhDbMunicipalities.map(x=>[String(x.id),x.name])),rm=new Map(adhDbRegions.map(x=>[String(x.id),x.name]));
 chapters=adhDbChapters.map(c=>({id:c.id,name:c.name||'',city:mm.get(String(c.municipality_id))||'Município não vinculado',region:rm.get(String(c.region_id))||'Região não vinculada',municipality_id:c.municipality_id,region_id:c.region_id,president:c.president_name||'',vice_president:c.vice_president_name||'',status:adhStatusFromDb[c.status]||c.status||'Inativo',contact:'',address:c.address||'',published:c.is_public===true,chapter_number:c.chapter_number??null}));
 renderAll();
}
