function clearEventImage(){adhEventImageFile=null;adhEventImageRemoved=true;const data=document.getElementById('eventImageData'),file=document.getElementById('eventImageFile'),wrap=document.getElementById('eventImagePreviewWrap'),img=document.getElementById('eventImagePreview');if(data)data.value='';if(file)file.value='';if(img)img.removeAttribute('src');if(wrap)wrap.style.display='none';}
