function canViewPage(name){return rolePermissions(currentRole).pages.includes(name)}
function firstAllowedPage(){return rolePermissions(currentRole).pages[0]||'dashboard'}
function canEdit(kind,quiet=false){const ok=rolePermissions(currentRole).edit.includes(kind);if(!ok&&!quiet)toast('Esta ação não está disponível para o perfil selecionado.');return ok}
function changeRole(){currentRole=document.getElementById('roleSelect').value;document.getElementById('roleLabel').textContent=currentRole;const hints={'Administrador':'Todos os módulos e ações administrativas.','Diretor estadual':'Gestão estadual; acesso completo aos módulos operacionais.','Diretor regional':'Módulos operacionais e revisão; sem administração de usuários e regiões.','Representante de campo':'Módulos operacionais dentro do escopo designado.','Presidente de capítulo':'Eventos, relatórios e preletores do próprio capítulo.','Secretário autorizado':'Ações delegadas no capítulo autorizado.','Apoio Jovem':'Módulos ligados ao escopo de Apoio Jovem.','Apoio Feminino':'Módulos ligados ao escopo de Apoio Feminino.'};document.getElementById('roleHint').textContent=hints[currentRole];applyRole();const active=document.querySelector('.apage.on');const page=active?.id.replace('page-','')||'dashboard';if(!canViewPage(page))showPage(firstAllowedPage());log('Perfil de pré-visualização alterado',currentRole,'Simulação local, sem autenticação.');}
function applyRole(){
 const perms=rolePermissions(currentRole);
 document.querySelectorAll('.nav[data-page]').forEach(n=>{n.hidden=!perms.pages.includes(n.dataset.page)});
 document.querySelectorAll('.apage').forEach(p=>{const name=p.id.replace('page-','');if(!perms.pages.includes(name))p.classList.remove('on')});
 // Botões principais por módulo
 const moduleForPage={'members':'member','chapters':'chapter','regions':'region','events':'event','announcements':'announcement','reports':'report','speakers':'speaker','users':'user','audit':'audit'};
 Object.entries(moduleForPage).forEach(([page,kind])=>{const section=document.getElementById('page-'+page);if(!section)return;section.querySelectorAll('.adminhead > .btn.primary, .adminhead .btn.primary').forEach(b=>b.classList.toggle('role-hidden',!perms.edit.includes(kind)));});
 // Ações individuais nas tabelas: mostrar somente quando o perfil puder editar aquele tipo de registro.
 const tableKinds={'chapterRows':'chapter','eventRows':'event','reportRows':'report','speakerRows':'speaker','regionList':'region','municipalityRows':'region','userRows':'user'};
 Object.entries(tableKinds).forEach(([id,kind])=>{const root=document.getElementById(id);if(!root)return;root.querySelectorAll('button').forEach(b=>{const label=(b.textContent||'').trim().toLowerCase();const isMutation=/editar|desativar|reativar|ativar|revisão|aprovar|correções|reenvio|encaminhamento/.test(label)||label.includes('novo');if(isMutation)b.classList.toggle('role-hidden',!perms.edit.includes(kind));});});
 // Exports and read-only actions remain visible where the module itself is available.
 document.querySelectorAll('.apage').forEach(p=>{const name=p.id.replace('page-','');if(!perms.pages.includes(name))p.classList.remove('on')});
 const active=document.querySelector('.apage.on');if(!active||!perms.pages.includes(active.id.replace('page-',''))){const target=firstAllowedPage();document.getElementById('page-'+target)?.classList.add('on');document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('on',n.dataset.page===target));}
}
function exportCSV(kind){let rows=[],filename=kind+'.csv';if(kind==='chapters')rows=[['Capítulo','Município','Região','Presidente','Status','Publicado'],...chapters.map(c=>[c.name,c.city,c.region,c.president,c.status,isPublicChapter(c)?'Sim':'Não'])];if(kind==='events')rows=[['Evento','Capítulo','Data','Município','Status','Publicado'],...events.map(e=>[e.name,e.chapter,e.date,e.city,e.status,e.published?'Sim':'Não'])];if(kind==='reports')rows=[['Evento','Capítulo','Responsável','Status','Entrega','Atualizado'],...reports.map(r=>[r.eventName,r.chapter,r.owner,r.status,r.submitted,r.updated])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);log('CSV exportado',filename,rows.length-1+' registro(s)');toast('Exportação CSV gerada.')}
