function geoBounds(features){let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;const scan=c=>{if(typeof c[0]==='number'){minX=Math.min(minX,c[0]);maxX=Math.max(maxX,c[0]);minY=Math.min(minY,c[1]);maxY=Math.max(maxY,c[1])}else c.forEach(scan)};features.forEach(f=>scan(f.geometry.coordinates));return {minX,minY,maxX,maxY}}
function projectGeoPoint(pt,b,w=600,h=390,pad=10){const x=pad+(pt[0]-b.minX)/(b.maxX-b.minX)*(w-pad*2);const y=h-pad-(pt[1]-b.minY)/(b.maxY-b.minY)*(h-pad*2);return [x,y]}
function ringPath(ring,b){return ring.map((pt,i)=>{const [x,y]=projectGeoPoint(pt,b);return (i?'L':'M')+x.toFixed(2)+' '+y.toFixed(2)}).join(' ')+' Z'}
function polygonPath(geom,b){const polys=geom.type==='Polygon'?[geom.coordinates]:geom.coordinates;return polys.map(poly=>poly.map(r=>ringPath(r,b)).join(' ')).join(' ')}
const ADH_REGION_PALETTE={
 'Araranguá':'#0F766E','Blumenau':'#2563EB','Campos de Lages':'#7C3AED','Canoinhas':'#64748B','Chapecó':'#15803D','Concórdia':'#0891B2','Criciúma':'#C2410C','Curitibanos':'#9333EA','Florianópolis':'#EA580C','Itajaí':'#0D9488','Ituporanga':'#4F46E5','Joaçaba':'#A16207','Joinville':'#BE123C','Rio do Sul':'#4D7C0F','São Bento do Sul':'#475569','São Miguel do Oeste':'#166534','Tabuleiro':'#A21CAF','Tijucas':'#0369A1','Tubarão':'#B45309','Xanxerê':'#6D28D9'
};
function adhRegionColor(name){return ADH_REGION_PALETTE[name]||'#94A3B8'}
function adhMixColor(hex,amount=.68){const h=hex.replace('#','');const n=parseInt(h,16);const r=(n>>16)&255,g=(n>>8)&255,b=n&255;const mix=v=>Math.round(v+(255-v)*amount);return '#'+[mix(r),mix(g),mix(b)].map(v=>v.toString(16).padStart(2,'0')).join('')}
function adhChapterStatusColor(region,status){const base=adhRegionColor(region);const s=String(status||'').toLowerCase();if(['ativo','active','published','published_active'].includes(s))return base;if(['inativo','inactive'].includes(s))return '#A8B0BA';if(['em ativação','ativação','activation','in_activation'].includes(s))return adhMixColor(base,.66);if(['em reativação','reativação','reactivation','reactivating'].includes(s))return adhMixColor(base,.34);return base}
