async function loadOfficialMunicipalities(){
 try{
  const rows=await adhFetch('/rest/v1/municipalities?select=*&limit=1000',{headers:{Authorization:'Bearer '+ADH_SUPABASE_KEY}});
  if(!Array.isArray(rows)||!rows.length)throw new Error('A consulta não retornou municípios.');
  municipalities=rows.map(m=>({id:m.id,name:m.name||m.nome||'Município sem nome',ibge:String(m.ibge_code??m.ibge??m.codigo_ibge??''),region:'',status:'Ativo',notes:'Registro carregado do Supabase.',raw:m}));
  renderMunicipalities();
 }catch(e){
  const el=document.getElementById('territoryLoadStatus');if(el)el.textContent='Não foi possível carregar municípios do Supabase: '+(e.message||'erro de consulta');
  // Não importar silenciosamente dados externos para a lista administrativa: evitar misturar fonte oficial e registros locais.
 }
}
async function loadTerritoryFromSupabase(){
 const status=document.getElementById('territoryLoadStatus');if(status)status.textContent='Consultando regiões, municípios e vínculos no Supabase…';
 try{
  const [rr,mm,links]=await Promise.all([
   adhFetch('/rest/v1/regions?select=id,name,description,is_active,created_at,updated_at,director_name,field_representatives,state_code&limit=1000',{headers:{Authorization:'Bearer '+ADH_SUPABASE_KEY}}),
   adhFetch('/rest/v1/municipalities?select=*&limit=1000',{headers:{Authorization:'Bearer '+ADH_SUPABASE_KEY}}),
   adhFetch('/rest/v1/region_municipalities?select=id,municipality_id,region_id,valid_from,valid_until&valid_until=is.null&limit=1000',{headers:{Authorization:'Bearer '+ADH_SUPABASE_KEY}})
  ]);
  if(!Array.isArray(rr)||!Array.isArray(mm))throw new Error('Formato inesperado retornado pelo banco.');
  adhCacheWrite('regions',rr);adhCacheWrite('municipalities',mm);
  adhDbRegions=rr;adhDbMunicipalities=mm;
  regions=rr.map(r=>({id:r.id,name:r.name||r.region_name||('Região #'+r.id),status:r.is_active===false||r.status==='inactive'?'Inativa':'Ativa',director:'',notes:'Carregada do Supabase.',raw:r}));
  const muniRegion=new Map();
  if(Array.isArray(links))links.forEach(x=>{const mid=x.municipality_id??x.municipio_id;const rid=x.region_id??x.regiao_id;if(mid!=null&&rid!=null)muniRegion.set(String(mid),String(rid));});
  const rnames=new Map(regions.map(r=>[String(r.id),r.name]));
  municipalities=mm.map(m=>{const id=String(m.id),rid=muniRegion.get(id)??(m.region_id!=null?String(m.region_id):null);return {id:m.id,name:m.name||m.nome||'Município sem nome',ibge:String(m.ibge_code??m.ibge??m.codigo_ibge??''),region:rid?(rnames.get(rid)||('Região #'+rid)):'Não vinculada',status:'Ativo',notes:'Carregado do Supabase.',raw:m};});
  renderRegions();renderMunicipalities();
  if(status)status.textContent=`Dados reais carregados: ${regions.length} regiões, ${municipalities.length} municípios${Array.isArray(links)?' e '+links.length+' vínculos municipais':' (vínculos não consultados)'}.`;
 }catch(e){if(status)status.textContent='Falha ao carregar a estrutura territorial: '+(e.message||'erro inesperado')+'. Os dados não foram substituídos por registros fictícios.';console.error('loadTerritoryFromSupabase',e)}
}

