function announcementPublic(a){const now=Date.now();return a.status==='published'&&(!a.startsAt||new Date(a.startsAt).getTime()<=now)&&(!a.endsAt||new Date(a.endsAt).getTime()>=now)}








function openAnnouncementPublic(id){const a=statewideAnnouncements.find(x=>x.id===id&&announcementPublic(x));if(!a)return;const content=`<div class="modal open" id="announcementReadModal" onclick="if(event.target===this)this.remove()"><div class="modalbox"><div class="modalhead"><div><div class="eyebrow">Comunicado estadual</div><h2>${esc(a.title)}</h2></div><button class="btn" onclick="document.getElementById('announcementReadModal').remove()">Fechar</button></div><p>${esc(a.summary)}</p><div style="white-space:pre-wrap;line-height:1.7">${esc(a.body)}</div><div class="actions" style="margin-top:16px">${a.actionUrl&&a.actionLabel?`<a class="btn primary" href="${esc(adhSafeUrl(a.actionUrl))}" target="_blank" rel="noopener">${esc(a.actionLabel)}</a>`:''}<button class="btn" onclick="document.getElementById('announcementReadModal').remove()">Fechar</button></div></div></div>`;document.body.insertAdjacentHTML('beforeend',content)}
function init(){safeLoad();chapters=[];events=[];speakers=[];reports=[];audit=[];regions=[];municipalities=[];users=[];statewideAnnouncements=[];try{Object.keys(localStorage).filter(k=>k.startsWith('adhonep_3v4_demo_')||k.startsWith('adhonep_v5_')).forEach(k=>localStorage.removeItem(k))}catch(e){}document.querySelectorAll('.muni,.pin').forEach(el=>el.addEventListener('click',()=>{const city=el.dataset.city;document.getElementById('publicCity').value=[...document.getElementById('publicCity').options].some(o=>o.value===city)?city:'';document.getElementById('findChapter').value=city;renderPublic();document.getElementById('publicList').scrollIntoView({behavior:'smooth',block:'nearest'})}));renderAll();if(adhSession)loadPersistentModules().catch(e=>{console.warn('Módulos persistentes indisponíveis:',e.message);toast('Não foi possível carregar os módulos do Supabase: '+e.message)});loadEventsFromSupabase(true).then(()=>{window.adhPublicEventsUnavailable=false;renderAll()}).catch(e=>{events=[];window.adhPublicEventsUnavailable=true;const target=document.getElementById('publicEvents');if(target)target.innerHTML='<div class="panel" style="grid-column:1/-1"><p class="sub">Agenda temporariamente indisponível. Tente novamente mais tarde.</p></div>';console.warn('Agenda pública indisponível; nenhum evento demonstrativo será exibido.',e.message)});const startInput=document.querySelector('#announcementFormIntegrated [name=startsAt]');if(startInput)startInput.value=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);/* O carregamento territorial administrativo exige sessão autenticada. A consulta pública é iniciada após a camada Supabase estar definida no segundo script. */}
document.addEventListener('DOMContentLoaded', init, { once: true });

function adhDialog({title,message,input=false,confirmLabel='Confirmar'}){return new Promise(res=>{const m=document.createElement('div');m.className='modal open';m.innerHTML=`<div class="modalbox" style="max-width:460px"><h3>${esc(title)}</h3><p class="sub">${esc(message||'')}</p>${input?'<textarea class="field" rows="3" id="adhDlgInput"></textarea>':''}<div class="actions" style="justify-content:flex-end;margin-top:14px"><button class="btn" data-k="0">Cancelar</button><button class="btn primary" data-k="1">${esc(confirmLabel)}</button></div></div>`;document.body.appendChild(m);m.addEventListener('click',e=>{const k=e.target.dataset&&e.target.dataset.k;if(k===undefined)return;const v=(m.querySelector('#adhDlgInput')||{}).value||'';m.remove();res(k==='1'?(input?v:true):(input?null:false))})})}

/* ===== v1.4: perfis reais, preletores (CSV e responsáveis), comunicados estadual/regional ===== */
function adhRealPermissions(){if(!adhProfile)return null;const r=adhProfile.role;let p=null;if(r==='chapter_president')p={pages:['chapters','events','reports','speakers','members'],edit:['event','report','member']};else if(r==='regional_director')p={pages:['dashboard','chapters','regions','events','announcements','reports','speakers'],edit:['chapter','event','announcement']};else if(r==='coordinator')p={pages:['events','announcements'],edit:['event']};else if(r==='state_director')p={pages:['dashboard','chapters','events','announcements','reports','speakers','audit'],edit:['chapter','event','announcement','report','speaker']};else if(r==='member')p={pages:[],edit:[]};else if(r==='speaker_editor')p={pages:['speakers'],edit:['speaker']};if(p&&adhProfile.speakerEditor){if(!p.edit.includes('speaker'))p.edit.push('speaker');if(!p.pages.includes('speakers'))p.pages.push('speakers')}return p}
function adhContactHtml(c,fallback){const d=String(c&&c.contact||'').replace(/\D/g,'');if(/^55\d{10,11}$/.test(d)){const n=d.slice(2),f='('+n.slice(0,2)+') '+(n.length===11?n.slice(2,7)+'-'+n.slice(7):n.slice(2,6)+'-'+n.slice(6));return (c.president?'<p>Presidente: '+esc(c.president)+'</p>':'')+'<p><a class="btn small primary" style="display:inline-block;text-decoration:none" href="https://wa.me/'+d+'?text='+encodeURIComponent('Olá! Vi o capítulo '+(c.name||'')+' no site da ADHONEP-SC e gostaria de mais informações.')+'" target="_blank" rel="noopener">Falar com o presidente no WhatsApp</a><br><span class="meta">'+f+'</span></p>'}return '<p>Contato: '+esc(c&&c.contact||fallback||'')+'</p>'}
function adhMyChapters(){if(adhProfile&&(adhProfile.role==='chapter_president'||adhProfile.role==='coordinator')){const mine=(adhProfile.chapterIds||[]).map(String);return chapters.filter(c=>mine.includes(String(c.id)))}if(adhProfile&&adhProfile.role==='regional_director'){const rg=(adhProfile.regionIds||[]).map(String);return chapters.filter(c=>rg.includes(String(c.region_id)))}return chapters}
function adhEventVisible(e){if(adhProfile&&['chapter_president','coordinator','regional_director'].includes(adhProfile.role)){return adhMyChapters().some(c=>String(c.name)===String(e.chapter))}return true}
function adhCsvCell(v){let t=String(v??'');if(/^[=+\-@\t\r]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"'}
function downloadSpeakersCSV(){if(!speakers.length){toast('Não há preletores para baixar.');return}const rows=[['Nome','Profissão','Capítulo','Atuação','Status','Telefone','Biografia'],...speakers.map(p=>[p.name,p.profession,p.chapter,p.type,p.status,p.phone,p.bio])];const csv='\ufeff'+rows.map(r=>r.map(adhCsvCell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const l=document.createElement('a');l.href=url;l.download='preletores-adhonep-sc.csv';document.body.appendChild(l);l.click();l.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
let adhSpeakerEditors=[];
async function loadSpeakerEditors(){const r=await adhFetch('/rest/v1/rpc/adh_list_speaker_editors',{method:'POST',body:'{}'});adhSpeakerEditors=Array.isArray(r)?r:[];renderSpeakerEditorsPanel()}
function renderSpeakerEditorsPanel(){const p=document.getElementById('speakerEditorsPanel');if(!p)return;const ok=!!(adhSession&&adhProfile&&['state_admin','state_director'].includes(adhProfile.role));p.hidden=!ok;if(!ok)return;document.getElementById('speakerEditorsList').innerHTML=adhSpeakerEditors.map(e=>`<tr><td>${esc(e.email)}</td><td><button class="btn small danger" onclick="revokeSpeakerEditor('${esc(String(e.user_id))}')">Remover</button></td></tr>`).join('')||'<tr><td colspan="2" class="empty">Nenhum responsável designado.</td></tr>'}
async function grantSpeakerEditor(ev){ev.preventDefault();const f=ev.target;try{await requireSession();await adhFetch('/rest/v1/rpc/adh_grant_speaker_editor',{method:'POST',body:JSON.stringify({p_email:String(f.elements.email.value||'').trim()})});f.reset();await loadSpeakerEditors();toast('Responsável designado. Ele precisa entrar de novo para ver a mudança.')}catch(e){toast('Não foi possível designar: '+e.message)}}
async function revokeSpeakerEditor(uid){try{if(!(await adhDialog({title:'Remover responsável',message:'Essa pessoa deixará de poder editar a lista de preletores.',confirmLabel:'Remover'})))return;await requireSession();await adhFetch('/rest/v1/rpc/adh_revoke_speaker_editor',{method:'POST',body:JSON.stringify({p_user:uid})});await loadSpeakerEditors();toast('Responsável removido.')}catch(e){toast('Não foi possível remover: '+e.message)}}
/* --- comunicados --- */
let adhRegionsList=[];
async function loadRegionsList(){try{adhRegionsList=(await adhFetch('/rest/v1/regions?select=id,name&order=name.asc&limit=100'))||[]}catch(e){adhRegionsList=[]}}
function adhRegionName(id){const r=adhRegionsList.find(x=>String(x.id)===String(id));return r?r.name:('Região #'+id)}
function annCanManage(a){if(!adhProfile)return false;if(['state_admin','state_director'].includes(adhProfile.role))return true;return adhProfile.role==='regional_director'&&a.scope==='regional'&&adhProfile.regionIds.map(String).includes(String(a.regionId))}
function annScopeChanged(){const f=document.getElementById('announcementFormIntegrated');if(!f)return;const reg=f.elements.scope.value==='regional';document.getElementById('annRegionWrap').style.display=reg?'':'none';f.elements.regionId.required=reg}
function annFormSetup(){const f=document.getElementById('announcementFormIntegrated');if(!f)return;const isReg=!!(adhProfile&&adhProfile.role==='regional_director');const mine=isReg?adhProfile.regionIds.map(String):null;const regs=isReg?adhRegionsList.filter(r=>mine.includes(String(r.id))):adhRegionsList;f.elements.regionId.innerHTML=regs.map(r=>`<option value="${esc(String(r.id))}">${esc(r.name)}</option>`).join('');if(isReg){f.elements.scope.value='regional';f.elements.scope.disabled=true}else f.elements.scope.disabled=false;annScopeChanged()}
function annLocalInput(iso){if(!iso)return '';const d=new Date(iso);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
function resetAnnouncementForm(){editingAnnouncementId=null;const f=document.getElementById('announcementFormIntegrated');f.reset();document.getElementById('announcementFormHeading').textContent='Novo comunicado';annFormSetup()}
async function saveAnnouncementIntegrated(ev){ev.preventDefault();if(!canEdit('announcement'))return;try{await requireSession();const f=ev.target,d=new FormData(f),start=d.get('startsAt'),end=d.get('endsAt');if(end&&new Date(end)<new Date(start))throw new Error('A data final deve ser posterior à inicial.');const isReg=!!(adhProfile&&adhProfile.role==='regional_director');const scope=isReg?'regional':String(d.get('scope')||'state');const regionId=scope==='regional'?Number(d.get('regionId')):null;if(scope==='regional'&&!regionId)throw new Error('Escolha a região do comunicado.');const id=editingAnnouncementId,cur=id?statewideAnnouncements.find(x=>String(x.id)===String(id)):null;const publishNow=d.get('publishNow')==='on';const data={title:d.get('title').trim(),category:d.get('category'),priority:d.get('priority'),summary:d.get('summary').trim(),body:d.get('body').trim(),starts_at:new Date(start).toISOString(),ends_at:end?new Date(end).toISOString():null,action_label:d.get('actionLabel').trim()||null,action_url:d.get('actionUrl').trim()||null,show_popup:d.get('showPopup')==='on',scope,region_id:regionId,status:publishNow?'published':(cur?cur.status:'draft')};const rows=await adhFetch('/rest/v1/statewide_announcements'+(id?'?id=eq.'+encodeURIComponent(id):''),{method:id?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(data)});if(!Array.isArray(rows)||!rows.length)throw new Error('O banco não confirmou a gravação (verifique permissões).');await loadPersistentModules();resetAnnouncementForm();renderAll();toast(data.status==='published'?'Comunicado publicado.':'Comunicado salvo.')}catch(e){toast('Não foi possível salvar o comunicado: '+e.message)}}
function editAnnouncementIntegrated(id){const a=statewideAnnouncements.find(x=>String(x.id)===String(id));if(!a||!annCanManage(a)){toast('Você não pode editar este comunicado.');return}editingAnnouncementId=a.id;const f=document.getElementById('announcementFormIntegrated');annFormSetup();for(const k of ['title','category','priority','summary','body','actionLabel','actionUrl'])if(f.elements[k])f.elements[k].value=a[k]||'';f.elements.startsAt.value=annLocalInput(a.startsAt);f.elements.endsAt.value=annLocalInput(a.endsAt);f.elements.showPopup.checked=!!a.showPopup;f.elements.publishNow.checked=false;if(!f.elements.scope.disabled)f.elements.scope.value=a.scope||'state';annScopeChanged();if(a.scope==='regional')f.elements.regionId.value=String(a.regionId);document.getElementById('announcementFormHeading').textContent='Editar comunicado';f.scrollIntoView({behavior:'smooth',block:'start'})}
async function setAnnouncementStatus(id,status){try{const a=statewideAnnouncements.find(x=>String(x.id)===String(id));if(!a||!annCanManage(a))throw new Error('Sem permissão para este comunicado.');await requireSession();const rows=await adhFetch('/rest/v1/statewide_announcements?id=eq.'+encodeURIComponent(id),{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({status})});if(!Array.isArray(rows)||!rows.length)throw new Error('O banco não confirmou a alteração.');await loadPersistentModules();renderAll();toast({published:'Comunicado publicado.',draft:'Comunicado despublicado (rascunho).',archived:'Comunicado arquivado.'}[status]||'Atualizado.')}catch(e){toast('Não foi possível atualizar: '+e.message)}}
function renderAnnouncementsIntegrated(){const root=document.getElementById('announcementRecords');if(!root)return;const q=document.getElementById('announcementApprovals');if(q)q.innerHTML='';const nav=document.getElementById('announcementNavCount');if(nav)nav.textContent='';const list=[...statewideAnnouncements].filter(annCanManage).sort((x,y)=>(y.createdAt||'').localeCompare(x.createdAt||''));document.getElementById('announcementTotal').textContent=list.length+' registro(s)';root.innerHTML=list.map(a=>{const btn=(label,onclick,cls='')=>`<button class="btn small ${cls}" onclick="${onclick}">${label}</button>`;let acts='';if(a.status==='draft')acts=btn('Publicar',`setAnnouncementStatus('${esc(a.id)}','published')`,'primary')+btn('Editar',`editAnnouncementIntegrated('${esc(a.id)}')`)+btn('Arquivar',`setAnnouncementStatus('${esc(a.id)}','archived')`);else if(a.status==='published')acts=btn('Despublicar',`setAnnouncementStatus('${esc(a.id)}','draft')`)+btn('Editar',`editAnnouncementIntegrated('${esc(a.id)}')`)+btn('Arquivar',`setAnnouncementStatus('${esc(a.id)}','archived')`);else acts=btn('Reativar como rascunho',`setAnnouncementStatus('${esc(a.id)}','draft')`);return `<div class="detail" style="margin:0 0 10px;background:white"><div class="statusline"><span class="tag ${a.status==='published'?'active':a.status==='archived'?'inactive':''}">${a.status==='published'?'Publicado':a.status==='archived'?'Arquivado':'Rascunho'}</span><span class="tag activation">${a.scope==='regional'?'Regional · '+esc(adhRegionName(a.regionId)):'Estadual'}</span>${a.priority==='urgent'?'<span class="tag inactive">Urgente</span>':a.priority==='important'?'<span class="tag activation">Importante</span>':''}</div><strong>${esc(a.title)}</strong><p>${esc(a.summary)}</p><div class="meta">${esc(a.category)} · Início: ${announcementDateLabel(a.startsAt)}</div><div class="actions" style="margin-top:9px">${acts}</div></div>`}).join('')||'<div class="empty">Nenhum comunicado.</div>'}

/* ===== v1.5: revelação suave das seções ao rolar ===== */
document.addEventListener('DOMContentLoaded',()=>{try{const els=document.querySelectorAll('#publicView .section .head,#publicView .section .panel,#publicView .cards .infocard');if(!('IntersectionObserver' in window)){return}const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.08});els.forEach(n=>{n.classList.add('js-reveal');io.observe(n)});setTimeout(()=>els.forEach(n=>n.classList.add('in')),4000)}catch(e){}});

/* ---- v2.4: botão Excluir (somente administrador) ---- */
(function(){const _ra=renderAll;renderAll=function(){_ra.apply(this,arguments);try{adhInjectDeletes()}catch(e){}}})();

/* v3.2 · links de comunicados: só http(s) */
function adhSafeUrl(u){try{const x=new URL(String(u||''),location.href);return(x.protocol==='https:'||x.protocol==='http:')?x.href:'#'}catch(e){return'#'}}
